(7654, 'ruRU', 'Императорские латные сапоги', '', '', NULL, 'Вернитесь к Деротайну Грязеглоту в Танарис.', NULL, NULL, NULL, NULL, 0),
(7655, 'ruRU', 'Императорские латные наручи', '', '', NULL, 'Вернитесь к Деротайну Грязеглоту в Танарис.', NULL, NULL, NULL, NULL, 0),
