(13017, 'ruRU', 'Предок Яртен', '', '', NULL, NULL, NULL, NULL, NULL, NULL, 0),
(13018, 'ruRU', 'Предок Сандрин', '', '', NULL, NULL, NULL, NULL, NULL, NULL, 0),
(13019, 'ruRU', 'Предок Тойм', '', '', NULL, NULL, NULL, NULL, NULL, NULL, 0),
