(25246, 'ruRU', 'Перемены в душе', '', '', NULL, 'Вернитесь к Орму Кающемуся.', NULL, NULL, NULL, NULL, 0),
(25247, 'ruRU', 'Перемены в душе', '', '', NULL, 'Вернитесь к Орму Кающемуся.', NULL, NULL, NULL, NULL, 0),
(25248, 'ruRU', 'Перемены в душе', '', '', NULL, 'Вернитесь к Орму Кающемуся.', NULL, NULL, NULL, NULL, 0),
